import { test } from "node:test";
import assert from "node:assert/strict";
import { total } from "../../src/cart/index.ts";

test("orders of $100 or more get 10% off", () => {
  assert.equal(total([{ sku: "lamp", priceCents: 5000, qty: 3 }]), 13500);
  assert.equal(total([{ sku: "rug", priceCents: 10000, qty: 1 }]), 9000);
});

test("smaller orders are unchanged", () => {
  assert.equal(total([{ sku: "mug", priceCents: 2500, qty: 2 }]), 5000);
});
